1	// The fleet overview: every member at once, worst first, with a way into any one of
2	// them. `fleet.mjs` decides what the rows MEAN; this file fetches and draws them.
3	
4	import * as gh from './github.mjs';
5	import {
6	  summariseMember, rankMembers, rollUp, packSpread, taskSpread,
7	} from './fleet.mjs';
8	import {
9	  $, el, ago, duration, head, emptyRow, repoLink, tiles, segmentBar,
10	  reasonNodes, LEVEL_GLYPH, STATE_ORDER, STATE_COLOR, STATE_UI, OUTCOME_COLOR,
11	} from './ui.mjs';
12	import { OUTCOME_DONE, OUTCOME_DELIVERED, OUTCOME_OBSOLETE } from '../../engine/scheduler/queue/work-item.mjs';
13	
14	// Members are read concurrently, but not all at once: a dozen members at six calls
15	// each is enough parallel load to trip secondary rate limiting, and the page is not
16	// in a hurry. Small and steady beats a burst that gets throttled.
17	const CONCURRENCY = 4;
18	
19	async function pool(items, worker, limit = CONCURRENCY) {
20	  const out = new Array(items.length);
21	  let next = 0;
22	  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
23	    for (;;) {
24	      const i = next; next += 1;
25	      if (i >= items.length) return;
26	      out[i] = await worker(items[i], i);
27	    }
28	  });
29	  await Promise.all(runners);
30	  return out;
31	}
32	
33	// One member's raw reads. Everything is wrapped: a member that 404s, times out or is
34	// rate-limited becomes a row that SAYS SO, because one unreadable repo must not blank
35	// the other eleven.
36	async function readMember(repo, token, { withTree = true } = {}) {
37	  try {
38	    const meta = await gh.getRepo(repo, token);
39	    const sha = await gh.getHeadSha(repo, meta.default_branch, token);
40	    const configText = await gh.getTextAtSha(repo, sha, '.claudinite-checks.json', token);
41	
42	    let declaration = null;
43	    if (configText) {
44	      try { declaration = JSON.parse(configText); } catch { declaration = null; }
45	    }
46	
47	    // A member that does not run Claudinite needs no further reads — and skipping
48	    // them is most of the saving on a fleet where not everything is adopted.
49	    if (!declaration) return { repo, declaration: null, defaultBranch: meta.default_branch };
50	
51	    const [tree, issuePage, runs] = await Promise.all([
52	      withTree ? gh.listTreeAtSha(repo, sha, token).catch(() => null) : Promise.resolve(null),
53	      // One page is the whole live queue plus recent history, which is all a fleet row
54	      // needs. Deep history is the per-repo view's job.
55	      gh.listIssues(repo, token, { pages: 1 }).catch(() => ({ issues: [] })),
56	      gh.listRuns(repo, token, 30).catch(() => []),
57	    ]);
58	
59	    return {
60	      repo,
61	      declaration,
62	      defaultBranch: meta.default_branch,
63	      sha,
64	      paths: tree?.paths ?? null,
65	      items: issuePage.issues,
66	      runs,
67	    };
68	  } catch (error) {
69	    return { repo, error };
70	  }
71	}
72	
73	// The canon reference the mount column compares against. Optional by design: with no
74	// `canonRepo` configured the column reads `unknown` rather than inventing `current`,
75	// and no repo name is ever hardcoded in engine code.
76	async function readCanon(config, token) {
77	  if (!config?.canonRepo) return null;
78	  try {
79	    const meta = await gh.getRepo(config.canonRepo, token);
80	    const ref = await gh.getHeadSha(config.canonRepo, meta.default_branch, token);
81	    const text = await gh.getTextAtSha(config.canonRepo, ref, '.claudinite-checks.json', token);
82	    let engineVersion = null;
83	    try { engineVersion = JSON.parse(text ?? '{}')?.claudinite?.engineVersion ?? null; } catch { /* absent */ }
84	    return { repo: config.canonRepo, ref, engineVersion };
85	  } catch {
86	    return null;
87	  }
88	}
89	
90	// --- render ---------------------------------------------------------------------
91	
92	const MOUNT_UI = {
93	  current: { label: 'current', cls: 'ok' },
94	  behind: { label: 'behind', cls: 'info' },
95	  'behind-engine': { label: 'old engine', cls: 'serious' },
96	  stalled: { label: 'stalled', cls: 'warning' },
97	  none: { label: 'no stamp', cls: 'warning' },
98	  unknown: { label: '—', cls: 'idle' },
99	};
100	
101	function memberRow(s, onOpen, now) {
102	  const open = (e) => { e.preventDefault(); onOpen(s.repo); };
103	
104	  const name = el('td', {}, [
105	    el('a', { href: `?repo=${encodeURIComponent(s.repo)}`, className: 'name', textContent: s.repo.split('/')[1] ?? s.repo, onclick: open }),
106	    el('div', { className: 'sub' }, [repoLink(s.repo)]),
107	  ]);
108	
109	  if (s.status !== 'adopted') {
110	    return el('tr', { className: `lvl-${s.level} muted-row` }, [
111	      name,
112	      el('td', { colSpan: 5 }, reasonNodes(s.reasons)),
113	      el('td', { className: 'nw' }, [el('a', { href: `?repo=${encodeURIComponent(s.repo)}`, textContent: 'open', onclick: open })]),
114	    ]);
115	  }
116	
117	  // Health: the worst reason, spelled out. Never a bare colour.
118	  const health = el('td', {}, s.reasons.length
119	    ? reasonNodes(s.reasons)
120	    : [el('span', { className: 'warn ok', textContent: `${LEVEL_GLYPH.ok} healthy` })]);
121	
122	  // Queue: the state mix as one thin bar plus the counts that are non-zero, so a
123	  // member with nothing open reads as empty rather than as a row of zeros.
124	  const counts = STATE_ORDER.filter((st) => s.open.byState[st] > 0)
125	    .map((st) => `${s.open.byState[st]} ${STATE_UI[st].label}`);
126	  const queue = el('td', {}, [
127	    segmentBar(STATE_ORDER.map((st) => [STATE_UI[st].label, s.open.byState[st], STATE_COLOR[st]]), { width: 92 }),
128	    el('div', { className: 'sub', textContent: counts.length ? counts.join(' · ') : 'nothing open' }),
129	  ]);
130	
131	  const outcomeBar = segmentBar([
132	    ['done', s.outcomes[OUTCOME_DONE], OUTCOME_COLOR[OUTCOME_DONE]],
133	    ['delivered', s.outcomes[OUTCOME_DELIVERED], OUTCOME_COLOR[OUTCOME_DELIVERED]],
134	    ['obsolete', s.outcomes[OUTCOME_OBSOLETE], OUTCOME_COLOR[OUTCOME_OBSOLETE]],
135	    ['no outcome', s.outcomes.none, OUTCOME_COLOR.none],
136	  ], { width: 92 });
137	
138	  const activity = el('td', {}, [
139	    outcomeBar,
140	    el('div', { className: 'sub', textContent: s.lastActivity ? ago(s.lastActivity, now) : (s.closedSeen ? 'unknown' : 'nothing closed yet') }),
141	  ]);
142	
143	  const runs = el('td', { className: 'nw' }, [
144	    el('div', {
145	      className: s.runs.consecutiveFailures ? 'warn critical' : 'sub',
146	      textContent: s.runs.consecutiveFailures
147	        ? `${LEVEL_GLYPH.critical} ${s.runs.consecutiveFailures} failing`
148	        : (s.runs.everRan ? 'passing' : 'never run'),
149	    }),
150	    el('div', { className: 'sub', textContent: s.runs.lastAt ? ago(s.runs.lastAt, now) : '—' }),
151	  ]);
152	
153	  const m = MOUNT_UI[s.mount.state] ?? MOUNT_UI.unknown;
154	  const mount = el('td', { className: 'nw' }, [
155	    el('div', { className: `warn ${m.cls}`, textContent: m.label }),
156	    el('div', { className: 'sub num', textContent: s.mount.ref ? s.mount.ref.slice(0, 7) : '—' }),
157	  ]);
158	
159	  const tasks = el('td', { className: 'num nw' }, [
160	    el('div', { textContent: s.declaredTasks == null ? '—' : String(s.declaredTasks) }),
161	    el('div', { className: 'sub', textContent: `${s.packs.length} packs` }),
162	  ]);
163	
164	  return el('tr', { className: `lvl-${s.level}` }, [name, health, queue, activity, runs, mount, tasks]);
165	}
166	
167	// A member whose read has not landed yet. It is a row from the first paint rather
168	// than a gap that fills in, because a fleet page that appears all at once at the end
169	// looks broken for the whole sweep — and on a slow or throttled read, the sweep is
170	// most of the time the viewer spends here.
171	const pendingRow = (repo) => el('tr', { className: 'pending-row' }, [
172	  el('td', {}, [
173	    el('span', { className: 'name', textContent: repo.split('/')[1] ?? repo }),
174	    el('div', { className: 'sub' }, [repoLink(repo)]),
175	  ]),
176	  el('td', { colSpan: 6 }, [el('span', { className: 'sub', textContent: 'reading…' })]),
177	]);
178	
179	function renderFleet(summaries, reads, now, onOpen, canon, progress = null) {
180	  const resolved = summaries.filter(Boolean);
181	  const pending = summaries.map((s, i) => (s ? null : reads.names?.[i])).filter(Boolean);
182	  const roll = rollUp(resolved);
183	
184	  tiles($('fleet-tiles'), [
185	    [roll.needAttention, 'members need you', roll.needAttention ? 'var(--critical)' : null,
186	      roll.needAttention ? 'parked, failing, or past a leash' : 'nothing is on fire'],
187	    [roll.parkedItems, 'items parked', roll.parkedItems ? 'var(--critical)' : null,
188	      roll.parkedMembers ? `across ${roll.parkedMembers} member(s)` : ''],
189	    [roll.failingMembers, 'schedulers failing', roll.failingMembers ? 'var(--critical)' : null,
190	      roll.neverRan ? `${roll.neverRan} never ran` : ''],
191	    [roll.behindMembers, 'mounts behind', roll.behindMembers ? 'var(--serious)' : null,
192	      canon ? `canon ${canon.ref.slice(0, 7)}` : 'no canon configured'],
193	    [roll.openItems, 'open work items', null, `${roll.inFlight} run(s) in flight`],
194	    [`${roll.adopted}/${roll.members}`, 'members adopted', null,
195	      [roll.notAdopted ? `${roll.notAdopted} not adopted` : '', roll.unreadable ? `${roll.unreadable} unreadable` : ''].filter(Boolean).join(', ')],
196	  ]);
197	
198	  // Every number above is a number about the members READ SO FAR, and a partial
199	  // rollup that does not say so is a wrong one. The count is stated rather than the
200	  // page waiting to be sure.
201	  $('fleet-progress').textContent = progress && progress.done < progress.total
202	    ? `${progress.done}/${progress.total} repos read — figures below cover those`
203	    : (progress ? `${progress.total} repos read` : '');
204	
205	  const body = head($('fleet'), ['Member', 'Health', 'Queue', 'Recent outcomes', 'Scheduler', 'Mount', 'Tasks']);
206	  if (!summaries.length) { body.append(emptyRow(7, 'No members in the roster.')); return; }
207	  for (const s of rankMembers(resolved)) body.append(memberRow(s, onOpen, now));
208	  for (const repo of pending) body.append(pendingRow(repo));
209	
210	  // Tasks across the fleet. This is the view a per-repo page structurally cannot
211	  // give: a shared pack's task parked in four members at once is a canon problem,
212	  // and in any single repo it looks like that repo's bad luck.
213	  const spread = taskSpread(reads.filter(Boolean), now).filter((t) => t.members > 0);
214	  const tbody = head($('fleet-tasks'), ['Task', 'Members', 'Open', 'Parked', 'Succeeded', 'No outcome']);
215	  if (!spread.length) tbody.append(emptyRow(6, 'No work items seen across the fleet.'));
216	  for (const t of spread.slice(0, 25)) {
217	    tbody.append(el('tr', { className: t.parked ? 'lvl-critical' : '' }, [
218	      el('td', {}, [
219	        el('div', { className: 'name', textContent: t.task }),
220	        el('div', { className: 'sub', textContent: t.pack }),
221	      ]),
222	      el('td', { className: 'num', textContent: String(t.members) }),
223	      el('td', { className: 'num', textContent: String(t.open) }),
224	      el('td', {}, t.parked
225	        ? [el('span', { className: 'warn critical', textContent: `${LEVEL_GLYPH.critical} ${t.parked}` })]
226	        : [el('span', { className: 'sub', textContent: '0' })]),
227	      el('td', { className: 'num', textContent: String(t.done) }),
228	      el('td', {}, t.failed
229	        ? [el('span', { className: 'warn serious', textContent: `${LEVEL_GLYPH.serious} ${t.failed}` })]
230	        : [el('span', { className: 'sub', textContent: '0' })]),
231	    ]));
232	  }
233	
234	  const packs = packSpread(resolved);
235	  $('fleet-packs').replaceChildren(...packs.map((p) =>
236	    el('span', { className: 'chip', title: `${p.members} member(s)` }, [
237	      p.pack, el('b', { className: 'count', textContent: String(p.members) }),
238	    ])));
239	}
240	
241	// --- entry ----------------------------------------------------------------------
242	
243	export async function loadFleet({ repos, token, config, onOpen, onError, onProgress }) {
244	  gh.resetCounters();
245	  const now = Date.now();
246	
247	  const canon = await readCanon(config, token);
248	
249	  // Rendered on every arrival rather than once at the end: the page is useful from
250	  // the first member back, and the member a viewer opened it for may be the first.
251	  const reads = new Array(repos.length).fill(null);
252	  reads.names = repos;
253	  const summaries = new Array(repos.length).fill(null);
254	  let done = 0;
255	  const paint = () => renderFleet(summaries, reads, now, onOpen, canon, { done, total: repos.length });
256	  paint();
257	
258	  await pool(repos, async (repo, i) => {
259	    const r = await readMember(repo, token);
260	    reads[i] = r;
261	    summaries[i] = summariseMember(r, { now, canon });
262	    done += 1;
263	    onProgress?.(done, repos.length, repo);
264	    paint();
265	    return r;
266	  });
267	  const failed = summaries.filter((s) => s?.status === 'unreadable');
268	  // Surfaced once at the top rather than as twelve separate errors: on a fleet, some
269	  // members being invisible to you is the normal case, not an incident.
270	  if (failed.length === repos.length && repos.length > 0) {
271	    onError?.(`None of the ${repos.length} members could be read — check that you are signed in with an account that can see them.`);
272	  }
273	
274	  paint();
275	  return { summaries: summaries.filter(Boolean), now, canon };
276	}
277

