1	import { finding } from '../../../../engine/checks/helpers/findings.mjs';
2	
3	// A PACK'S CONTENT IS DELIVERED ON ITS VERSION NUMBER, and on nothing else. The
4	// engine tree vendors wholesale on every converge; a pack's directory ships only
5	// where `planPackUpdates` sees `installed.packVersions[id] < pack.version`
6	// (updates/pack-update.mjs). So a canon commit that edits `packs/<id>/` without
7	// touching that number lands here, goes green here, and reaches no member — the
8	// fleet keeps the old bytes while canon believes the change shipped.
9	//
10	// #939 is what that costs. A check vocabulary rename updated the engine and the
11	// canon's own packs in one commit: the engine, delivered unconditionally, reached
12	// every member and rejected the old spelling; the pack carrying the new spelling
13	// stayed at `version: 1` and reached nobody. The mixed tree failed each member's
14	// self-test, the update PR parked, and the fix could not arrive by the route that
15	// delivers fixes. Seven repos sat frozen for five days.
16	//
17	// So the invariant this rule holds is one line: A CHANGE UNDER `packs/<id>/` IS A
18	// CHANGE TO THAT PACK'S VERSION. Every byte counts, because every byte ships in
19	// the same directory copy — prose, a skill, a check module, a migration record.
20	// It is the pack-side twin of `engine-release-record` (the claudinite local pack),
21	// which holds the same line for `ENGINE_VERSION`.
22	//
23	// WORK SCOPE: the question is what THIS change did. The tree always contains a
24	// version number; only the diff says whether it moved with the content beside it.
25	const LOCAL_PACKS = '.claudinite/local/packs';
26	
27	// The pack ids a changed-file list touches, in first-seen order. Anchored at
28	// `packs/<id>/` so the canon's own local packs (which vendor nowhere, carry no
29	// version and reach no member) and the tree's own files (`packs/README.md`,
30	// `packs/directory.GENERATED.md`) are outside it by construction.
31	export function packsTouched(changed) {
32	  const ids = [];
33	  for (const file of changed ?? []) {
34	    if (file.startsWith(`${LOCAL_PACKS}/`)) continue;
35	    const m = /^packs\/([^/]+)\//.exec(file);
36	    if (m && !ids.includes(m[1])) ids.push(m[1]);
37	  }
38	  return ids;
39	}
40	
41	// The `version:` a pack manifest declares, or null when it declares none (a
42	// manifest that is absent on one side of the diff, or one the schema check owns).
43	// The preceding-character class is what keeps `minEngineVersion:` out of it.
44	export function declaredPackVersion(text) {
45	  const m = /(?:^|[\s{,])version:\s*(\d+)/m.exec(text ?? '');
46	  return m ? Number(m[1]) : null;
47	}
48	
49	const rule = {
50	  id: 'pack-version-bumped',
51	  severity: 'blocking',
52	  scope: 'work',
53	  description: 'A change under packs/<id>/ bumps that pack\'s version',
54	  doc: 'docs/versioned-updates/DESIGN.md',
55	  why: 'a member receives a pack directory only when the canon\'s version exceeds the one it has installed, so content edited without a bump reaches nobody while canon CI reports it shipped (#939 froze seven repos for five days that way)',
56	
57	  run(work) {
58	    const findings = [];
59	    for (const id of packsTouched(work.changedFiles)) {
60	      const manifest = `packs/${id}/pack.mjs`;
61	      const head = declaredPackVersion(work.read(manifest));
62	      if (head === null) continue;                     // the pack was deleted, or declares no version — other rules own that
63	      const base = declaredPackVersion(work.readBase(manifest));
64	      if (base === null) continue;                     // a pack this change introduces: its first version ships to everyone
65	      if (head > base) continue;
66	
67	      findings.push(finding(rule, {
68	        file: manifest,
69	        what: head === base
70	          ? `this change edits packs/${id}/ but leaves its version at ${head}`
71	          : `packs/${id}/ moves its version backwards, ${base} → ${head}`,
72	        fix: head === base
73	          ? `raise \`version\` in ${manifest} to ${base + 1} — the number is the whole delivery signal, so an edit that `
74	            + 'does not move it stays in the canon forever'
75	          : 'pack versions only ever increase — the update flow reads them as an ordering, so a lowered number tells '
76	            + 'every member it is already up to date',
77	      }));
78	    }
79	    return findings;
80	  },
81	};
82	
83	export default rule;
84

